CREATE OR REPLACE FUNCTION private.approve_sealed_site_contract(p_proposal uuid, p_company uuid, p_expected_revision integer, p_expected_seal_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p private.site_payment_proposals; pair jsonb; sender uuid; recipient uuid; seal jsonb; preview jsonb;
begin
 select * into p from private.site_payment_proposals where id=p_proposal;
 if p.id is null then raise exception '契約が見つかりません。'; end if;
 pair:=private.site_payment_pair(p.shared_item_id,p_company);
 perform 1 from private.site_payment_agreement_rollout r where r.company_id in
  ((pair->>'parent_company_id')::uuid,(pair->>'child_company_id')::uuid)
  order by r.company_id for share;
 perform 1 from private.company_connections c where
  c.parent_company_id=(pair->>'parent_company_id')::uuid and
  c.child_company_id=(pair->>'child_company_id')::uuid for share;
 perform 1 from private.site_share_inbox where data_item_id=p.shared_item_id for update;
 pair:=private.site_payment_pair(p.shared_item_id,p_company);
 select d.sender_company_id,d.recipient_company_id into sender,recipient
 from private.company_data_delivery_items i join private.document_deliveries d on d.id=i.delivery_id
 where i.id=p.shared_item_id;
 if recipient is distinct from p_company or not exists(select 1 from private.site_contract_seals
  where proposal_id=p_proposal and company_id=sender and action='sent') then
  raise exception '受信側管理者のみ送信済み注文書を承認できます。' using errcode='42501';
 end if;
 if exists(select 1 from private.site_payment_proposals where shared_item_id=p.shared_item_id
  and revision>p.revision) then raise exception '最新版を確認してください。' using errcode='40001'; end if;
 if p_expected_revision is null or p_expected_revision<>p.revision then
  raise exception '最新版を確認してください。' using errcode='40001'; end if;
 -- Idempotent approval preserves the original actor, time and seal forever.
 select s.seal_snapshot into seal from private.site_contract_seals s
 where s.proposal_id=p_proposal and s.company_id=p_company;
 if found then
  if p_expected_seal_hash is null or p_expected_seal_hash is distinct from
   encode(sha256(convert_to(seal::text,'UTF8')),'hex') then
   raise exception '保存済みの押印内容を再確認してください。' using errcode='40001'; end if;
  return;
 end if;
 preview:=private.preview_site_contract_seal(p.shared_item_id,p_company,p_proposal);
 if p_expected_seal_hash is null or p_expected_seal_hash is distinct from preview->>'seal_hash' then
  raise exception '会社角印が変更されました。プレビューを再確認してください。' using errcode='40001'; end if;
 seal:=preview->'seal_snapshot';
 insert into private.site_contract_seals values(p_proposal,p_company,auth.uid(),'approved',seal,now());
 perform private.confirm_site_payment_terms(p_proposal,p_company);
 insert into private.site_contract_notification_outbox(proposal_id,company_id,event,payload)
 select p_proposal,cid,'terms_approved',jsonb_build_object('action_key','site_payment_agreement',
  'shared_item_id',p.shared_item_id,'proposal_id',p_proposal,'company_id',cid,'event','terms_approved')
 from unnest(array[sender,recipient]) cid on conflict do nothing;
end $function$

CREATE OR REPLACE FUNCTION private.confirm_site_payment_terms(p_proposal uuid, p_company uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare proposal private.site_payment_proposals; pair jsonb;
begin
 select * into proposal from private.site_payment_proposals where id=p_proposal;
 if proposal.id is null then raise exception '提案が見つかりません。'; end if;
 pair:=private.site_payment_pair(proposal.shared_item_id,p_company);
 perform 1 from private.site_payment_agreement_rollout r where r.company_id in
  ((pair->>'parent_company_id')::uuid,(pair->>'child_company_id')::uuid)
  order by r.company_id for share;
 perform 1 from private.company_connections c where c.parent_company_id=(pair->>'parent_company_id')::uuid
  and c.child_company_id=(pair->>'child_company_id')::uuid for share;
 perform 1 from private.site_share_inbox where data_item_id=proposal.shared_item_id for update;
 pair:=private.site_payment_pair(proposal.shared_item_id,p_company);
 if exists(select 1 from private.site_payment_proposals p where
  p.shared_item_id=proposal.shared_item_id and p.revision>proposal.revision)
 then raise exception '古い提案は確認できません。' using errcode='40001'; end if;
 insert into private.site_payment_confirmations(proposal_id,company_id,confirmed_by)
 values(p_proposal,p_company,auth.uid()) on conflict do nothing;
end $function$

CREATE OR REPLACE FUNCTION private.preview_site_contract_seal(p_item uuid, p_company uuid, p_proposal uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pair jsonb; seal jsonb; current_revision integer; sender uuid; recipient uuid;
begin
 pair:=private.site_payment_pair(p_item,p_company);
 perform 1 from private.site_payment_agreement_rollout r where r.company_id in
  ((pair->>'parent_company_id')::uuid,(pair->>'child_company_id')::uuid)
  order by r.company_id for share;
 perform 1 from private.company_connections c where
  c.parent_company_id=(pair->>'parent_company_id')::uuid and
  c.child_company_id=(pair->>'child_company_id')::uuid for share;
 perform 1 from private.site_share_inbox where data_item_id=p_item for update;
 pair:=private.site_payment_pair(p_item,p_company);
 select d.sender_company_id,d.recipient_company_id into sender,recipient
 from private.company_data_delivery_items i join private.document_deliveries d on d.id=i.delivery_id
 where i.id=p_item;
 select coalesce(max(p.revision),0) into current_revision from private.site_payment_proposals p where p.shared_item_id=p_item;
 if p_proposal is null then
  if sender is distinct from p_company then raise exception '共有元管理者のみ送信できます。' using errcode='42501'; end if;
 elsif recipient is distinct from p_company or not exists(select 1 from private.site_payment_proposals p
  join private.site_contract_seals s on s.proposal_id=p.id and s.company_id=sender and s.action='sent'
  where p.id=p_proposal and p.shared_item_id=p_item and p.revision=current_revision) then
  raise exception '最新版の送信済み契約を受信側で確認してください。' using errcode='40001';
 end if;
 -- The official snapshot helper locks the same company row as seal settings.
 perform 1 from public.companies where id=p_company for share;
 if not exists(select 1 from public.companies where id=p_company and company_seal_enabled) then
  raise exception '会社角印を有効にしてください。' using errcode='55000'; end if;
 seal:=private.document_company_seal_snapshot(null,p_company,true)->'company_seal_snapshot';
 if seal is null or jsonb_typeof(seal)<>'object' or seal='{}'::jsonb then
  raise exception '会社角印を設定してください。'; end if;
 -- Recheck after the company-row lock wait; never reuse a pre-wait capability.
 perform private.site_payment_pair(p_item,p_company);
 return jsonb_build_object('company_id',p_company,'shared_item_id',p_item,
  'proposal_id',p_proposal,'revision',current_revision,'seal_snapshot',seal,
  'atomic_seal_version',1,'rollout_enabled',true,
  'sender_company_id',sender,'recipient_company_id',recipient,
  'can_send',p_proposal is null and p_company=sender,
  'can_approve',p_proposal is not null and p_company=recipient and not exists(
   select 1 from private.site_contract_seals s where s.proposal_id=p_proposal and s.company_id=p_company),
  'seal_hash',encode(sha256(convert_to(seal::text,'UTF8')),'hex'));
end $function$

CREATE OR REPLACE FUNCTION private.propose_site_payment_terms(p_item uuid, p_company uuid, p_expected_revision integer, p_terms jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pair jsonb; current_revision integer; proposal uuid; amount numeric; base numeric;
 item jsonb; adjustment numeric:=0; mode text; rounding text;
begin
 pair:=private.site_payment_pair(p_item,p_company);
 perform 1 from private.site_payment_agreement_rollout r where r.company_id in
  ((pair->>'parent_company_id')::uuid,(pair->>'child_company_id')::uuid)
  order by r.company_id for share;
 perform 1 from private.company_connections c where c.parent_company_id=(pair->>'parent_company_id')::uuid
  and c.child_company_id=(pair->>'child_company_id')::uuid for share;
 -- Serialize both parties on the existing canonical shared-site inbox row.
 perform 1 from private.site_share_inbox where data_item_id=p_item for update;
 pair:=private.site_payment_pair(p_item,p_company);
 select coalesce(max(revision),0) into current_revision from private.site_payment_proposals
 where shared_item_id=p_item;
 if p_expected_revision is null or current_revision<>p_expected_revision then raise exception '最新の提案を再読込してください。' using errcode='40001'; end if;
 if p_terms is null or jsonb_typeof(p_terms)<>'object' then raise exception '金額条件が必要です。'; end if;
 if p_terms::text ~* '"(NaN|[-+]?Infinity)"' then raise exception '有限の金額・数量が必要です。'; end if;
 if (p_terms->>'period_start')::date is null or (p_terms->>'period_end')::date is null
 or (p_terms->>'period_end')::date<(p_terms->>'period_start')::date
 then raise exception '対象期間が必要です。'; end if;
 mode:=p_terms->>'mode'; rounding:=p_terms->>'rounding_rule';
 if mode not in ('square_meter','lump_sum') or mode is null or rounding is null
 or rounding not in ('floor','nearest','ceil') then raise exception '計算方式・端数処理を選択してください。'; end if;
 base:=private.site_payment_finite_number(p_terms->'base_amount_yen');
 if base is null or base<0 or base<>trunc(base) then raise exception '基本額が不正です。'; end if;
 if mode='square_meter' then
  if coalesce(private.site_payment_finite_number(p_terms->'unit_price_yen'),-1)<0 or
   private.site_payment_finite_number(p_terms->'unit_price_yen')<>trunc(private.site_payment_finite_number(p_terms->'unit_price_yen')) or
   coalesce(private.site_payment_finite_number(p_terms->'area'),-1)<0 then raise exception '平米単価と平米数が必要です。'; end if;
  amount:=private.site_payment_finite_number(p_terms->'unit_price_yen')*private.site_payment_finite_number(p_terms->'area');
  amount:=case rounding when 'floor' then floor(amount) when 'ceil' then ceil(amount) else round(amount) end;
  if base<>amount then raise exception '平米計算の総額が一致しません。'; end if;
 end if;
 if jsonb_typeof(p_terms->'adjustments') is distinct from 'array' then raise exception '追加項目が必要です。'; end if;
 for item in select value from jsonb_array_elements(p_terms->'adjustments') loop
  if nullif(trim(item->>'name'),'') is null or item->>'direction' is null or item->>'direction' not in ('addition','deduction')
   or coalesce(private.site_payment_finite_number(item->'amount_yen'),-1)<0
   or private.site_payment_finite_number(item->'amount_yen')<>trunc(private.site_payment_finite_number(item->'amount_yen'))
  then raise exception '追加項目が不正です。'; end if;
  adjustment:=adjustment+private.site_payment_finite_number(item->'amount_yen')*
   case item->>'direction' when 'deduction' then -1 else 1 end;
 end loop;
 if jsonb_typeof(p_terms->'tax_included') is distinct from 'boolean' or
  coalesce(private.site_payment_finite_number(p_terms->'tax_amount_yen'),-1)<0 or
  private.site_payment_finite_number(p_terms->'tax_amount_yen')<>trunc(private.site_payment_finite_number(p_terms->'tax_amount_yen')) or
  coalesce(private.site_payment_finite_number(p_terms->'tax_rate'),-1)<0 or
  coalesce(private.site_payment_finite_number(p_terms->'taxable_amount_yen'),-1)<0 then raise exception '税条件が必要です。'; end if;
 amount:=private.site_payment_finite_number(p_terms->'taxable_amount_yen')*private.site_payment_finite_number(p_terms->'tax_rate')/100;
 amount:=case rounding when 'floor' then floor(amount) when 'ceil' then ceil(amount) else round(amount) end;
 if private.site_payment_finite_number(p_terms->'tax_amount_yen')<>amount and nullif(trim(p_terms->>'tax_override_reason'),'') is null
 then raise exception '税額が税率・課税対象・端数処理と一致しません。手動変更理由が必要です。'; end if;
 amount:=base+adjustment+case when (p_terms->>'tax_included')::boolean then 0
  else private.site_payment_finite_number(p_terms->'tax_amount_yen') end;
 if amount<0 or amount<>coalesce(private.site_payment_finite_number(p_terms->'final_amount_yen'),-1)
 then raise exception '最終額が一致しません。'; end if;
 insert into private.site_payment_proposals(shared_item_id,revision,proposed_company_id,proposed_by,terms)
 values(p_item,current_revision+1,p_company,auth.uid(),p_terms) returning id into proposal;
 return proposal;
end $function$

CREATE OR REPLACE FUNCTION private.saved_site_payment_document(p_proposal uuid, p_company uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare proposal private.site_payment_proposals; pair jsonb; result jsonb;
begin
 select * into proposal from private.site_payment_proposals where id=p_proposal;
 if proposal.id is null then raise exception '提案が見つかりません。'; end if;
 pair:=private.site_payment_pair(proposal.shared_item_id,p_company);
 perform 1 from private.site_payment_agreement_rollout r where r.company_id in
  ((pair->>'parent_company_id')::uuid,(pair->>'child_company_id')::uuid)
  order by r.company_id for share;
 perform 1 from private.company_connections c where c.parent_company_id=(pair->>'parent_company_id')::uuid
  and c.child_company_id=(pair->>'child_company_id')::uuid for share;
 perform 1 from private.site_share_inbox where data_item_id=proposal.shared_item_id for update;
 pair:=private.site_payment_pair(proposal.shared_item_id,p_company);
 if exists(select 1 from private.site_payment_proposals p where p.shared_item_id=proposal.shared_item_id
  and p.revision>proposal.revision) then raise exception '最新版を確認してください。' using errcode='40001'; end if;
 if not exists(select 1 from private.site_payment_confirmations c where c.proposal_id=p_proposal
  and c.company_id=(pair->>'parent_company_id')::uuid) or not exists(
  select 1 from private.site_payment_confirmations c where c.proposal_id=p_proposal
  and c.company_id=(pair->>'child_company_id')::uuid) then raise exception '双方の確認が必要です。'; end if;
 select snapshot into result from private.site_payment_document_snapshots where proposal_id=p_proposal;
 if result is null then
  select jsonb_build_object('proposal_id',proposal.id,'revision',proposal.revision,'terms',proposal.terms,
   'parent_company_name',parent.name,'subcontractor_company_name',child.name,'site_name',s.name,
   'parent_company_id',parent.id,'subcontractor_company_id',child.id,
   'snapshot_version',3,
   'parent_postal_code',coalesce(parent.postal_code,''),
   'parent_address',coalesce(parent.address,''),
   'parent_phone',coalesce(parent.phone,''),
   'parent_fax',coalesce(parent.fax,''),
   'parent_company_seal_enabled',parent.company_seal_enabled)||private.document_company_seal_snapshot(null,parent.id,true)
  into result from public.companies parent,public.companies child,public.sites s
  where parent.id=(pair->>'parent_company_id')::uuid and child.id=(pair->>'child_company_id')::uuid
  and s.id=(pair->>'source_site_id')::uuid;
  insert into private.site_payment_document_snapshots(proposal_id,snapshot,created_by)
  values(p_proposal,result,auth.uid());
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.send_sealed_site_contract(p_item uuid, p_company uuid, p_expected_revision integer, p_terms jsonb, p_expected_seal_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pair jsonb; sender uuid; recipient uuid; proposal uuid; seal jsonb; start_day date; preview jsonb;
begin
 pair:=private.site_payment_pair(p_item,p_company);
 perform 1 from private.site_payment_agreement_rollout r where r.company_id in
  ((pair->>'parent_company_id')::uuid,(pair->>'child_company_id')::uuid)
  order by r.company_id for share;
 perform 1 from private.company_connections c where
  c.parent_company_id=(pair->>'parent_company_id')::uuid and
  c.child_company_id=(pair->>'child_company_id')::uuid for share;
 -- Hold the canonical pair before proposal creation, capturing the same actor,
 -- connection and rollout authorization used by existing agreement functions.
 perform 1 from private.site_share_inbox where data_item_id=p_item for update;
 pair:=private.site_payment_pair(p_item,p_company);
 select d.sender_company_id,d.recipient_company_id into sender,recipient
 from private.company_data_delivery_items i
 join private.document_deliveries d on d.id=i.delivery_id where i.id=p_item;
 if sender is distinct from p_company then
  raise exception '現場の共有元管理者が押印して送信してください。' using errcode='42501';
 end if;
 start_day:=(p_terms->>'effective_from')::date;
 if start_day is null or start_day<(p_terms->>'period_start')::date
  or start_day>(p_terms->>'period_end')::date then
  raise exception '対象期間内の適用開始日が必要です。';
 end if;
 -- Never accept client-supplied seal or approver identity.
 if p_terms ?| array['company_seal_snapshot','seal_snapshot','approved_by','actor_id'] then
  raise exception '印影・承認者はサーバーで記録します。';
 end if;
 preview:=private.preview_site_contract_seal(p_item,p_company,null);
 if p_expected_seal_hash is null or p_expected_seal_hash is distinct from preview->>'seal_hash' then
  raise exception '会社角印が変更されました。プレビューを再確認してください。' using errcode='40001'; end if;
 seal:=preview->'seal_snapshot';
 proposal:=private.propose_site_payment_terms(p_item,p_company,p_expected_revision,p_terms);
 insert into private.site_contract_seals values(proposal,p_company,auth.uid(),'sent',seal,now());
 perform private.confirm_site_payment_terms(proposal,p_company);
 insert into private.site_contract_notification_outbox(proposal_id,company_id,event,payload)
 select proposal,cid,'terms_sent',jsonb_build_object('action_key','site_payment_agreement',
  'shared_item_id',p_item,'proposal_id',proposal,'company_id',cid,'event','terms_sent')
 from unnest(array[sender,recipient]) cid;
 return proposal;
end $function$

CREATE OR REPLACE FUNCTION private.get_site_contract_notification_target(p_notification uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare notice public.app_notifications; event private.site_contract_notification_outbox; item uuid;
begin
 if auth.uid() is null or not private.account_access_allowed() then
  raise exception '通知を開く権限がありません。' using errcode='42501'; end if;
 select n.* into notice from public.app_notifications n
 join private.site_contract_notification_receipts r on r.notification_id=n.id and r.recipient_user_id=auth.uid()
 where n.id=p_notification and n.recipient_user_id=auth.uid() and n.action_key='site_payment_agreement';
 if notice.id is null then raise exception '通知を開く権限がありません。' using errcode='42501'; end if;
 select o.* into event from private.site_contract_notification_outbox o
 join private.site_contract_notification_receipts r on r.outbox_id=o.id where r.notification_id=notice.id;
 select shared_item_id into item from private.site_payment_proposals where id=event.proposal_id;
 if event.company_id is distinct from notice.company_id or item is distinct from notice.action_id then
  raise exception '通知の対象を確認できません。' using errcode='42501'; end if;
 perform private.site_payment_pair(item,notice.company_id);
 return jsonb_build_object('company_id',notice.company_id,'shared_item_id',item,
  'proposal_id',event.proposal_id,'event',event.event);
end $function$
